"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

PAGE_SIZE = 100

QUERY = """
query Settlements($first: Int!, $after: String) {
  settlements(first: $first, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}
"""


def graphql(url, query, variables=None):
    body = json.dumps({"query": query, "variables": variables or {}}).encode()
    while True:
        req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
            break
        except urllib.error.HTTPError as e:
            if e.code != 429:
                raise
            # A 429 is transient: wait as instructed, then resend the identical request.
            delay = e.headers.get("Retry-After")
            time.sleep(float(delay) if delay else 1)
    if result.get("errors"):
        raise RuntimeError(result["errors"])
    return result["data"]


def fetch_settlements(url):
    # Retry a traversal from scratch if the cursor is rejected as malformed/expired.
    for attempt in range(3):
        settlements = {}
        after = None
        try:
            while True:
                data = graphql(url, QUERY, {"first": PAGE_SIZE, "after": after})["settlements"]
                # An amended settlement is delivered again later; the last version wins.
                for s in data["nodes"]:
                    settlements[s["id"]] = s
                page = data["pageInfo"]
                # Short or empty pages are not the end; only hasNextPage is.
                if not page["hasNextPage"]:
                    break
                after = page["endCursor"]
            return list(settlements.values())
        except RuntimeError:
            if attempt == 2:
                raise
    raise AssertionError("unreachable")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

